*{box-sizing:border-box}body{margin:0;background:#fff5fa;color:#492b47;font:15px/1.6 system-ui,sans-serif}main{max-width:1120px;margin:auto;padding:24px 16px 45px}.eyebrow{font-size:11px;font-weight:800;letter-spacing:2px;text-transform:uppercase;color:#a13c78}h1{font-size:clamp(30px,5vw,43px);line-height:1.2}h2{font-size:22px;margin:0 0 12px}h3{font-size:17px;margin:14px 0 6px}p{margin:8px 0;color:#806478}a{color:#96386f}label{display:block;font-weight:700;margin-bottom:4px}input,select{font:inherit;width:100%;padding:10px;border:1px solid #e1c4d7;border-radius:10px;background:white;color:#492b47}button{font:inherit;font-weight:700;background:#a13c78;color:#fff;border:0;border-radius:10px;padding:10px 16px;cursor:pointer}button.alt{background:#f4e0ef;color:#883363}.card{padding:20px;border:1px solid #efd5e4;background:#fffbfd;border-radius:18px;margin:15px 0}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.actions{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}.table{overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px}td,th{padding:9px;text-align:left;border-bottom:1px solid #efd5e4;white-space:nowrap}.selected{background:#f6e0ef;font-weight:700}.result{background:#f7eaf3;border-radius:12px;padding:12px;margin:12px 0;color:#6b325d}.note{font-size:13px;color:#806478}.shop-list a{display:block;padding:9px 0;border-bottom:1px solid #efd5e4}.footer{font-size:12px;color:#806478;margin-top:24px}@media(max-width:650px){.grid{grid-template-columns:1fr}.card{padding:15px}}
